# One-shot Windows/Linux PowerShell offline test. All generated bytes remain in
# a temporary CI sandbox. Never accesses real Mini-PC/Cloud/Scheduler/model.
$ErrorActionPreference='Stop'
$repo=Split-Path $PSScriptRoot -Parent
$script=Join-Path $repo 'tools/stage-minipc-v3-paper-inactive.ps1'
$tokens=$null;$errors=$null
[void][System.Management.Automation.Language.Parser]::ParseFile($script,[ref]$tokens,[ref]$errors)
if(@($errors).Count -gt 0){throw ('V3_STAGE_PARSE_FAILED '+($errors|Out-String))}
$source=Get-Content -LiteralPath $script -Raw
foreach($forbidden in @('Start-ScheduledTask','Stop-ScheduledTask',
    'Disable-ScheduledTask','Register-ScheduledTask','Set-ScheduledTask',
    'Invoke-WebRequest','Invoke-RestMethod','Start-Process',
    'git pull','git checkout','git clone',
    'supabase db','supabase functions deploy','api.openai.com',
    'PAPER_CAS_EXECUTE','-Force -Recurse')){
  if($source.IndexOf($forbidden,[StringComparison]::OrdinalIgnoreCase) -ge 0){
    throw ('V3_STAGE_MUTATION_COMMAND_FORBIDDEN '+$forbidden)
  }
}
foreach($required in @(
  'source_git_sha=$ExpectedSourceSha',
  'status='+[char]39+'READ_ONLY_SOURCE_PREFLIGHT_PASS_NOT_STAGED'+[char]39,
  'STAGED_INACTIVE_CODE_ONLY_NOT_INSTALLED',
  'git -C $source status --porcelain --untracked-files=normal',
  'ls-files --cached',
  'Copy-Item -LiteralPath $origin -Destination $destination',
  'Fingerprint $destination',
  'V3_SOURCE_ONLY_INACTIVE_NO_TASKS',
  'v3_paper_activated=$false','task_changes=$false',
  'model_calls=0','cloud_edge_deployed=$false',
  'release_proofs_credited=0','original_v2r4_unchanged=$true'
)){
  if(-not $source.Contains([string]$required)){throw ('V3_STAGE_SCOPE_GUARD_ABSENT '+$required)}
}
$root=Join-Path ([IO.Path]::GetTempPath()) ('v3-paper-stage-test-'+[guid]::NewGuid().ToString('N'))
try {
  New-Item -ItemType Directory -Path $root -ErrorAction Stop | Out-Null
  $independent=Join-Path $root 'independent-source'
  & git clone --quiet --local --no-hardlinks $repo $independent
  if($LASTEXITCODE -ne 0){throw 'Unable to isolate local CI checkout'}
  $head=(& git -C $independent rev-parse HEAD).Trim()
  if($LASTEXITCODE -ne 0 -or $head -cnotmatch '^[a-f0-9]{40}$'){throw 'CI Git source pin absent'}
  $trading=Join-Path $root 'Trading'
  New-Item -ItemType Directory -Path (Join-Path $trading 'Staging') -Force | Out-Null
  $expectedDir=Join-Path (Join-Path $trading 'Staging') ('V3Paper-INACTIVE-'+$head.Substring(0,12))

  $preview=& $script -SourceRoot $independent -ExpectedSourceSha $head -TradingRoot $trading |
      ConvertFrom-Json
  if($preview.status -cne 'READ_ONLY_SOURCE_PREFLIGHT_PASS_NOT_STAGED' -or
     $preview.source_git_sha -cne $head -or
     $preview.tracked_code_files -lt 20 -or
     $preview.v3_writer_installed -ne $false -or
     $preview.cloud_cas_performed -ne $false -or
     (Test-Path -LiteralPath $expectedDir)){throw 'Source preview failed read-only isolation'}

  $fail=$false
  try {
    & $script -SourceRoot $independent -ExpectedSourceSha ('f'*40) -TradingRoot $trading | Out-Null
  }catch{$fail=$true}
  if(-not $fail -or (Test-Path -LiteralPath $expectedDir)){throw 'Wrong source pin did not block'}

  Set-Content -LiteralPath (Join-Path $independent 'deliberately-untracked.txt') -Value 'CI-only'
  $fail=$false
  try {
    & $script -SourceRoot $independent -ExpectedSourceSha $head -TradingRoot $trading | Out-Null
  }catch{$fail=$true}
  if(-not $fail){throw 'Dirty independent source did not block'}
  Remove-Item -LiteralPath (Join-Path $independent 'deliberately-untracked.txt') -Force

  $fail=$false
  try {
    & $script -SourceRoot $independent -ExpectedSourceSha $head -TradingRoot $trading -Stage | Out-Null
  }catch{$fail=$true}
  if(-not $fail -or (Test-Path -LiteralPath $expectedDir)){throw 'Stage without explicit confirmation did not block'}

  $result=& $script -SourceRoot $independent -ExpectedSourceSha $head -TradingRoot $trading -Stage -Confirm 'V3_SOURCE_ONLY_INACTIVE_NO_TASKS' |
      ConvertFrom-Json
  if($result.status -cne 'STAGED_INACTIVE_CODE_ONLY_NOT_INSTALLED' -or
     $result.source_git_sha -cne $head -or
     $result.task_changes -ne $false -or $result.model_calls -ne 0 -or
     $result.real_money_actions -ne $false -or
     $result.release_proofs_credited -ne 0){
    throw 'Source-only stage incorrectly claims release or host state'
  }
  $saved=Join-Path $expectedDir 'v3-paper-inactive-source-manifest.json'
  if(-not(Test-Path -LiteralPath $saved -PathType Leaf)){throw 'Source manifest missing'}
  $stored=Get-Content -LiteralPath $saved -Raw | ConvertFrom-Json
  if($stored.source_git_sha -cne $head -or
     $stored.tracked_code_files -ne $result.tracked_code_files){throw 'Stage manifest source pin mismatch'}
  foreach($file in @($stored.source_manifest)){
    $relative=[string]$file.relative_path
    if($relative -notmatch '^(paper_evaluator|market_data)/[a-zA-Z0-9_]+\.py$' -and
       $relative -cne 'research/v3/v3-experimental-paper-all-lessons-bundle-20261011.json' -and
       $relative -cne 'supabase/functions/v3-paper-evidence-relay/index.ts'){
      throw ('Unreviewed staged path '+$relative)
    }
    $dest=Join-Path $expectedDir $relative
    $digest=([string](Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash).ToLowerInvariant()
    if($digest -cne [string]$file.sha256){throw ('Staged file digest mismatch '+$relative)}
  }
  $fail=$false
  try {
    & $script -SourceRoot $independent -ExpectedSourceSha $head -TradingRoot $trading -Stage -Confirm 'V3_SOURCE_ONLY_INACTIVE_NO_TASKS' | Out-Null
  }catch{$fail=$true}
  if(-not $fail){throw 'Existing stage was overwritten instead of refused'}
  Write-Host ('V3_PAPER_INACTIVE_SOURCE_STAGE_OFFLINE_6_CASES_PASS FILES='+$result.tracked_code_files)
} finally {
  if(Test-Path -LiteralPath $root){
    Remove-Item -LiteralPath $root -Recurse -Force -ErrorAction SilentlyContinue
  }
}
